insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('UZ', 'UZ-P-12', 'ҚҚС 12 % — асосий ставка (харид)', '{"en":"VAT 12% — standard rate (purchase)"}'::jsonb, null, 'percent', 12, 'purchase', 'domestic', date '2020-01-01', null, 'Солиқ кодекси, 266-модда — солиқ тўловчи ҳақиқатда олинган товарлар (хизматлар) бўйича тўланган (тўланиши лозим) солиқ суммасини, ҳисобварақ-фактура ёки солиқ суммаси алоҳида ажратилган ҳужжат мавжуд бўлганда ва етказиб берувчи солиқ тўловчи сифатида рўйхатдан ўтган бўлса, ҳисобга олиш ҳуқуқига эга; 267-модда — ҳисобга олинмайдиган солиқ суммаси (озод этилган айланма бўйича: 268-модда).', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-P-12-NR', 'ҚҚС 12 % — норезидент хизматлари (солиқ агенти)', '{"en":"VAT 12% — services from a non-resident (tax agent)"}'::jsonb, 'Хизматлар чет эллик шахсдан олинганда харидор солиқ агенти сифатида ҳисоблайдиган ва тўлангандан кейингина ҳисобга олинадиган ҚҚС', 'percent', 12, 'purchase', 'foreign_services_received', date '2020-01-01', null, 'Солиқ кодекси, 255-модда — Ўзбекистон ҳудуди реализация қилиш жойи бўлган хизматлар солиқ органларида ҳисобда турмаган чет эллик шахслар томонидан реализация қилинганда, харидор — юридик шахс солиқ агенти бўлиб, солиқни ҳисоблаб бюджетга тўлайди; 266-модда, 4-банд — бундай солиқ бюджетга тўланганда ҳисобга олинади. Ҳисобланган солиқ 6413 да, ҳисобга олиниши 4413 да кутади; тўлов ойида 4411 га ва INPUT ячейкасига кўчириш — қўлда киритиладиган ёзув (README.md).', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-S-12', 'ҚҚС 12 % — асосий ставка (сотув)', '{"en":"VAT 12% — standard rate (sale)"}'::jsonb, null, 'percent', 12, 'sale', 'domestic', date '2020-01-01', null, 'Солиқ кодекси, 258-модда, биринчи қисм — 36-бобда бошқача қоида белгиланмаган бўлса, солиқ ставкаси 12 фоиз миқдорида белгиланади (2023 йил 1 январдан, ЎРҚ-812-сон Қонун таҳририда).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-S-EXEMPT-EDU', 'ҚҚС дан озод — таълим соҳасидаги хизматлар (сотув)', '{"en":"VAT-exempt — education services (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-01-01', null, 'Солиқ кодекси, 243-модда, биринчи қисм, 10-банд — бошланғич, ўрта, ўрта махсус, профессионал, олий ва олий таълимдан кейинги таълим хизматлари, қўшимча таълим бериш хизматлари, тест синовлари ва имтиҳонларни ташкил этиш хизматлари солиқ солишдан озод этилади (243-модда охирги қисми: солиқ солинадиган ва озод этиладиган айланмаларнинг алоҳида ҳисоби — 268-модда).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-S-EXEMPT-FINANCIAL', 'ҚҚС дан озод — банк операциялари ва бошқа молиявий хизматлар (сотув)', '{"en":"VAT-exempt — banking operations and other financial services (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-01-01', null, 'Солиқ кодекси, 243-модда, биринчи қисм, 27-банд ва 244-модда — банк операциялари (қиймати қатъий суммада белгиланган хизматлардан ташқари), кредитлар ва қарзлар бериш, қимматли қоғозлар билан операциялар, факторинг ва шу кабилар солиқ солишдан озод этилади.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-S-ZERO-EXPORT', 'ҚҚС 0 % — товарлар экспорти (сотув)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2020-01-01', null, 'Солиқ кодекси, 258-модда, иккинчи қисм ва 260-модда — экспорт божхона тартиб-таомилига олиб чиқилган товарлар ва шунга тенглаштирилган операциялар ноль даражали ставка бўйича солиққа тортилади; тасдиқловчи ҳужжатлар (261-модда) солиқ ҳисоботи билан бирга тақдим этилади.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('UZ', 'UZ-S-ZERO-TRANSPORT', 'ҚҚС 0 % — халқаро ташишлар билан боғлиқ хизматлар (сотув)', '{"en":"VAT 0% — international transport services (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2020-01-01', null, 'Солиқ кодекси, 258-модда, иккинчи қисм ва 263-модда — товарларни халқаро ташиш, божхона транзити ва ягона халқаро ташиш ҳужжатлари бўйича йўловчилар, почта ва багажни ташиш хизматлари ноль ставка бўйича солиққа тортилади.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
