    ('UZ-P-12', 'credit_note', 'base', 100, null, 'INPUT', array['INPUT']::text[], -100, 'UZ-VAT', 10),
    ('UZ-P-12', 'credit_note', 'tax', 100, '4411', 'INPUT', array['INPUT']::text[], -100, 'UZ-VAT', 20),
    ('UZ-P-12-NR', 'invoice', 'base', 100, null, null, null, 100, null, 10),
    ('UZ-P-12-NR', 'invoice', 'tax', 100, '4413', null, null, 100, null, 20),
    ('UZ-P-12-NR', 'invoice', 'tax', -100, '6413', null, null, 100, null, 30),
    ('UZ-P-12-NR', 'credit_note', 'base', 100, null, null, null, 100, null, 10),
    ('UZ-P-12-NR', 'credit_note', 'tax', 100, '4413', null, null, 100, null, 20),
    ('UZ-P-12-NR', 'credit_note', 'tax', -100, '6413', null, null, 100, null, 30),
    ('UZ-S-12', 'invoice', 'base', 100, null, 'TAXABLE', array['TAXABLE']::text[], 100, 'UZ-VAT', 10),
    ('UZ-S-12', 'invoice', 'tax', 100, '6411', 'TAXABLE', array['TAXABLE']::text[], 100, 'UZ-VAT', 20),
    ('UZ-S-12', 'credit_note', 'base', 100, null, 'TAXABLE', array['TAXABLE']::text[], -100, 'UZ-VAT', 10),
    ('UZ-S-12', 'credit_note', 'tax', 100, '6411', 'TAXABLE', array['TAXABLE']::text[], -100, 'UZ-VAT', 20),
    ('UZ-S-EXEMPT-EDU', 'invoice', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], 100, 'UZ-VAT', 10),
    ('UZ-S-EXEMPT-EDU', 'credit_note', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], -100, 'UZ-VAT', 10),
    ('UZ-S-EXEMPT-FINANCIAL', 'invoice', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], 100, 'UZ-VAT', 10),
    ('UZ-S-EXEMPT-FINANCIAL', 'credit_note', 'base', 100, null, 'EXEMPT', array['EXEMPT']::text[], -100, 'UZ-VAT', 10),
    ('UZ-S-ZERO-EXPORT', 'invoice', 'base', 100, null, 'ZERO', array['ZERO']::text[], 100, 'UZ-VAT', 10),
    ('UZ-S-ZERO-EXPORT', 'credit_note', 'base', 100, null, 'ZERO', array['ZERO']::text[], -100, 'UZ-VAT', 10),
    ('UZ-S-ZERO-TRANSPORT', 'invoice', 'base', 100, null, 'ZERO', array['ZERO']::text[], 100, 'UZ-VAT', 10),
