insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('UZ', 'UZ-VAT', 'Қўшилган қиймат солиғи бўйича солиқ ҳисоботи', array['month']::declaration_period[], 'month'::declaration_period, date '2020-01-01', null, 'Солиқ кодекси, 259-модда — бир ой солиқ даври; 265-модда — солиқни ҳисоблаб чиқариш; 272-модда — тўланиши лозим бўлган солиқ суммаси; 273-модда — солиқ ҳисоботини тақдим этиш ва солиқни тўлаш тартиби (ҳисобот таркибига харидлар реестри ва сотувлар реестри маълумотлари киради). Ҳисобот шакли ва унинг сатр рақамларини тасдиқловчи ҳужжат матни ўқилмади; шунинг учун ячейкалар расмий шаклнинг сатр рақамлари билан эмас, Кодекс моддалари бўйича номланган (TAXABLE, ZERO, EXEMPT, TURNOVER, INPUT, CREDIT, PAYABLE, EXCESS). README.md га қаранг.', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Солиқ кодекси, 273-модда, биринчи ва иккинчи қисмлар — солиқ ҳисоботи ўтган солиқ давридан кейинги ойнинг йигирманчи кунидан кечиктирилмасдан тақдим этилади; солиқни тўлаш ҳисобот тақдим этиш муддатидан кечиктирмай амалга оширилади. Товарлар олиб кирилганда солиқ божхона қонунчилигидаги тартибда ва муддатларда тўланади (учинчи қисм).', 'tax-code', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
