values
  ('UZ-BS', 'UZ', 'default', 'Бухгалтерия баланси', 'balance_sheet', 'БҲМС', date '2025-01-01', null, '1-сонли БҲМС (иқтисодиёт ва молия вазирининг 2024 йил 14 июндаги 130-сон буйруғи, 3544-сон давлат рўйхати) молиявий ҳисоботнинг таркибини белгилайди; 21-сонли БҲМС ҳисобварақлар режасининг боблари ва гуруҳлари (0100–0999 узоқ муддатли активлар, 1000–5999 жорий активлар, 6000–7999 мажбуриятлар, 8000–8999 хусусий капитал) бўйича сатрлар йиғилган. Бу пакетнинг ўз йиғмаси, расмий баланс шакли эмас: шаклнинг матни (1-БҲМС иловаси) ўқилмади. README.md га қаранг. 1-БҲМС 2027 йил 1 январдан миллий молиявий ҳисобот стандарти (НСФО № 1) билан алмашади.', 'nsbu-1', 'combined', 'Жорий молиявий йил натижаси', '{"en":"Result of the current financial year"}'::jsonb),
  ('UZ-IS', 'UZ', 'default', 'Молиявий натижалар тўғрисидаги ҳисобот', 'income_statement', 'БҲМС', date '2025-01-01', null, '1-сонли БҲМС молиявий натижалар ҳисоботини молиявий ҳисобот таркибига киритади; сатрлар 21-сонли БҲМС ҳисобварақлар режасининг 9000–9899 гуруҳлари бўйича йиғилган (9900 «Якуний молиявий натижа» ёпувчи ҳисобварақ сифатида киритилмаган). Расмий шакл ўқилмади; README.md га қаранг.', 'nsbu-1', null, null, '{}'::jsonb)
