  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Солиқ кодекси, 242-модда — товарлар бўйича айланма амалга оширилган сана: ҳисобварақ-фактура тақдим этилган сана ёки товарлар жўнатилган сана (қайси бири олдин келса); хизматлар бўйича — хизмат кўрсатилганини тасдиқловчи ҳужжат расмийлаштирилган сана. Бу икки санадан «олдини» танлаш қоидаси формат билан ифодаланмайди: пакет етказиб бериш санасини олади; README.md га қаранг.',
  tax_point_source_key          = 'tax-code',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = 'Солиқ кодекси, 257-модда — солиқ базасига тузатиш товарлар қайтарилганда, хизматдан воз кечилганда, шартлар ва нарх ўзгарганда ва чегирмалар берилганда киритилади; ўтказилган ёзув ўчирилмайди, тузатувчи ҳужжат билан тўғриланади.',
  posted_edit_policy_source_key = 'tax-code',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Солиқ кодекси, 47-модда — ҳисобварақ-фактура, қоида тариқасида, электрон ҳисобварақ-фактураларнинг ахборот тизимида электрон шаклда расмийлаштирилади (Вазирлар Маҳкамасининг 2019 йил 25 июндаги 522-сон қарори билан тасдиқланган тартиб). Бу давлат тизими, EN 16931 семантик модели бўйича алмашув эмас: профиль, иштирокчи схемаси ва ҚҚС схемаси берилмаган; тизимга юбориш ядродан ташқарида (README.md).',
